BEGIN;
CREATE TABLE tenants (tenant_id varchar(64) PRIMARY KEY, name varchar(200) NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), status varchar(32) NOT NULL DEFAULT 'ACTIVE');
CREATE TABLE projects (project_id varchar(64) PRIMARY KEY, tenant_id varchar(64) NOT NULL REFERENCES tenants(tenant_id) ON DELETE RESTRICT, name varchar(200) NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), status varchar(32) NOT NULL DEFAULT 'ACTIVE', CONSTRAINT uq_project_tenant_name UNIQUE(tenant_id,name), CONSTRAINT uq_project_scope UNIQUE(tenant_id,project_id));
CREATE TABLE lots (lot_id varchar(64) PRIMARY KEY, tenant_id varchar(64) NOT NULL REFERENCES tenants(tenant_id) ON DELETE RESTRICT, project_id varchar(64) NOT NULL REFERENCES projects(project_id) ON DELETE RESTRICT, created_at timestamptz NOT NULL DEFAULT now(), created_by varchar(128) NOT NULL, updated_at timestamptz NOT NULL DEFAULT now(), updated_by varchar(128) NOT NULL, version integer NOT NULL DEFAULT 1 CHECK(version>=1), row_version integer NOT NULL DEFAULT 1 CHECK(row_version>=1), status varchar(48) NOT NULL, classification varchar(48) NOT NULL DEFAULT 'INTERNAL', trace_id varchar(96), correlation_id varchar(96), schema_version integer NOT NULL DEFAULT 1 CHECK(schema_version>=1), valid_from timestamptz, valid_to timestamptz, system_from timestamptz NOT NULL DEFAULT now(), system_to timestamptz, deleted_at timestamptz, deletion_reason text, title varchar(500) NOT NULL, payload jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE sources (source_id varchar(64) PRIMARY KEY, tenant_id varchar(64) NOT NULL REFERENCES tenants(tenant_id) ON DELETE RESTRICT, project_id varchar(64) NOT NULL REFERENCES projects(project_id) ON DELETE RESTRICT, created_at timestamptz NOT NULL DEFAULT now(), created_by varchar(128) NOT NULL, updated_at timestamptz NOT NULL DEFAULT now(), updated_by varchar(128) NOT NULL, version integer NOT NULL DEFAULT 1 CHECK(version>=1), row_version integer NOT NULL DEFAULT 1 CHECK(row_version>=1), status varchar(48) NOT NULL, classification varchar(48) NOT NULL DEFAULT 'INTERNAL', trace_id varchar(96), correlation_id varchar(96), schema_version integer NOT NULL DEFAULT 1 CHECK(schema_version>=1), valid_from timestamptz, valid_to timestamptz, system_from timestamptz NOT NULL DEFAULT now(), system_to timestamptz, deleted_at timestamptz, deletion_reason text, source_type varchar(64) NOT NULL, official_name varchar(500), canonical_url text, owner_name varchar(500), legal_decision varchar(32) NOT NULL DEFAULT 'DRAFT', passport jsonb NOT NULL DEFAULT '{}'::jsonb, CONSTRAINT uq_source_canonical_url UNIQUE(tenant_id,project_id,canonical_url));
CREATE TABLE source_versions (source_version_id varchar(64) PRIMARY KEY, tenant_id varchar(64) NOT NULL REFERENCES tenants(tenant_id) ON DELETE RESTRICT, project_id varchar(64) NOT NULL REFERENCES projects(project_id) ON DELETE RESTRICT, source_id varchar(64) REFERENCES sources(source_id) ON DELETE RESTRICT, created_at timestamptz NOT NULL DEFAULT now(), created_by varchar(128) NOT NULL, updated_at timestamptz NOT NULL DEFAULT now(), updated_by varchar(128) NOT NULL, version integer NOT NULL DEFAULT 1 CHECK(version>=1), row_version integer NOT NULL DEFAULT 1 CHECK(row_version>=1), status varchar(48) NOT NULL, classification varchar(48) NOT NULL DEFAULT 'INTERNAL', trace_id varchar(96), correlation_id varchar(96), schema_version integer NOT NULL DEFAULT 1 CHECK(schema_version>=1), valid_from timestamptz, valid_to timestamptz, system_from timestamptz NOT NULL DEFAULT now(), system_to timestamptz, deleted_at timestamptz, deletion_reason text, source_version integer NOT NULL, passport jsonb NOT NULL, content_sha256 varchar(64) NOT NULL, CONSTRAINT uq_source_version UNIQUE(source_id,source_version), CONSTRAINT uq_source_version_hash UNIQUE(source_id,content_sha256));
CREATE TABLE source_policies (source_policy_id varchar(64) PRIMARY KEY, tenant_id varchar(64) NOT NULL REFERENCES tenants(tenant_id) ON DELETE RESTRICT, project_id varchar(64) NOT NULL REFERENCES projects(project_id) ON DELETE RESTRICT, source_id varchar(64) REFERENCES sources(source_id) ON DELETE RESTRICT, created_at timestamptz NOT NULL DEFAULT now(), created_by varchar(128) NOT NULL, updated_at timestamptz NOT NULL DEFAULT now(), updated_by varchar(128) NOT NULL, version integer NOT NULL DEFAULT 1 CHECK(version>=1), row_version integer NOT NULL DEFAULT 1 CHECK(row_version>=1), status varchar(48) NOT NULL, classification varchar(48) NOT NULL DEFAULT 'INTERNAL', trace_id varchar(96), correlation_id varchar(96), schema_version integer NOT NULL DEFAULT 1 CHECK(schema_version>=1), valid_from timestamptz, valid_to timestamptz, system_from timestamptz NOT NULL DEFAULT now(), system_to timestamptz, deleted_at timestamptz, deletion_reason text, decision varchar(32) NOT NULL CHECK(decision IN ('APPROVED','CONDITIONAL','REJECTED')), permissions jsonb NOT NULL DEFAULT '{}'::jsonb, expires_at timestamptz);
CREATE TABLE connector_definitions (connector_id varchar(64) PRIMARY KEY, tenant_id varchar(64) NOT NULL REFERENCES tenants(tenant_id) ON DELETE RESTRICT, project_id varchar(64) NOT NULL REFERENCES projects(project_id) ON DELETE RESTRICT, source_id varchar(64) REFERENCES sources(source_id) ON DELETE RESTRICT, created_at timestamptz NOT NULL DEFAULT now(), created_by varchar(128) NOT NULL, updated_at timestamptz NOT NULL DEFAULT now(), updated_by varchar(128) NOT NULL, version integer NOT NULL DEFAULT 1 CHECK(version>=1), row_version integer NOT NULL DEFAULT 1 CHECK(row_version>=1), status varchar(48) NOT NULL, classification varchar(48) NOT NULL DEFAULT 'INTERNAL', trace_id varchar(96), correlation_id varchar(96), schema_version integer NOT NULL DEFAULT 1 CHECK(schema_version>=1), valid_from timestamptz, valid_to timestamptz, system_from timestamptz NOT NULL DEFAULT now(), system_to timestamptz, deleted_at timestamptz, deletion_reason text, connector_type varchar(64) NOT NULL, config_schema jsonb NOT NULL DEFAULT '{}'::jsonb, code_version varchar(128) NOT NULL, owner varchar(200) NOT NULL, checkpoint jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE collection_runs (run_id varchar(64) PRIMARY KEY, tenant_id varchar(64) NOT NULL REFERENCES tenants(tenant_id) ON DELETE RESTRICT, project_id varchar(64) NOT NULL REFERENCES projects(project_id) ON DELETE RESTRICT, source_id varchar(64) REFERENCES sources(source_id) ON DELETE RESTRICT, created_at timestamptz NOT NULL DEFAULT now(), created_by varchar(128) NOT NULL, updated_at timestamptz NOT NULL DEFAULT now(), updated_by varchar(128) NOT NULL, version integer NOT NULL DEFAULT 1 CHECK(version>=1), row_version integer NOT NULL DEFAULT 1 CHECK(row_version>=1), status varchar(48) NOT NULL, classification varchar(48) NOT NULL DEFAULT 'INTERNAL', trace_id varchar(96), correlation_id varchar(96), schema_version integer NOT NULL DEFAULT 1 CHECK(schema_version>=1), valid_from timestamptz, valid_to timestamptz, system_from timestamptz NOT NULL DEFAULT now(), system_to timestamptz, deleted_at timestamptz, deletion_reason text, connector_id varchar(64) NOT NULL REFERENCES connector_definitions(connector_id) ON DELETE RESTRICT, started_at timestamptz NOT NULL, finished_at timestamptz, result jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE artifacts (artifact_id varchar(64) PRIMARY KEY, tenant_id varchar(64) NOT NULL REFERENCES tenants(tenant_id) ON DELETE RESTRICT, project_id varchar(64) NOT NULL REFERENCES projects(project_id) ON DELETE RESTRICT, source_id varchar(64) REFERENCES sources(source_id) ON DELETE RESTRICT, created_at timestamptz NOT NULL DEFAULT now(), created_by varchar(128) NOT NULL, updated_at timestamptz NOT NULL DEFAULT now(), updated_by varchar(128) NOT NULL, version integer NOT NULL DEFAULT 1 CHECK(version>=1), row_version integer NOT NULL DEFAULT 1 CHECK(row_version>=1), status varchar(48) NOT NULL, classification varchar(48) NOT NULL DEFAULT 'INTERNAL', trace_id varchar(96), correlation_id varchar(96), schema_version integer NOT NULL DEFAULT 1 CHECK(schema_version>=1), valid_from timestamptz, valid_to timestamptz, system_from timestamptz NOT NULL DEFAULT now(), system_to timestamptz, deleted_at timestamptz, deletion_reason text, run_id varchar(64) REFERENCES collection_runs(run_id) ON DELETE SET NULL, mime_type varchar(255) NOT NULL, size_bytes bigint NOT NULL CHECK(size_bytes>=0), content_sha256 varchar(64) NOT NULL, storage_sha256 varchar(64) NOT NULL, storage_uri text NOT NULL, immutable boolean NOT NULL DEFAULT true, manifest jsonb NOT NULL DEFAULT '{}'::jsonb, CONSTRAINT uq_artifact_hash_uri UNIQUE(tenant_id,content_sha256,storage_uri));
CREATE TABLE snapshots (snapshot_id varchar(64) PRIMARY KEY, tenant_id varchar(64) NOT NULL REFERENCES tenants(tenant_id) ON DELETE RESTRICT, project_id varchar(64) NOT NULL REFERENCES projects(project_id) ON DELETE RESTRICT, source_id varchar(64) REFERENCES sources(source_id) ON DELETE RESTRICT, created_at timestamptz NOT NULL DEFAULT now(), created_by varchar(128) NOT NULL, updated_at timestamptz NOT NULL DEFAULT now(), updated_by varchar(128) NOT NULL, version integer NOT NULL DEFAULT 1 CHECK(version>=1), row_version integer NOT NULL DEFAULT 1 CHECK(row_version>=1), status varchar(48) NOT NULL, classification varchar(48) NOT NULL DEFAULT 'INTERNAL', trace_id varchar(96), correlation_id varchar(96), schema_version integer NOT NULL DEFAULT 1 CHECK(schema_version>=1), valid_from timestamptz, valid_to timestamptz, system_from timestamptz NOT NULL DEFAULT now(), system_to timestamptz, deleted_at timestamptz, deletion_reason text, run_id varchar(64) REFERENCES collection_runs(run_id) ON DELETE SET NULL, captured_at timestamptz NOT NULL, manifest jsonb NOT NULL, snapshot_sha256 varchar(64) NOT NULL, CONSTRAINT uq_snapshot_source_hash UNIQUE(source_id,snapshot_sha256));
CREATE TABLE snapshot_artifacts (snapshot_id varchar(64) NOT NULL REFERENCES snapshots(snapshot_id) ON DELETE RESTRICT, artifact_id varchar(64) NOT NULL REFERENCES artifacts(artifact_id) ON DELETE RESTRICT, ordinal integer NOT NULL DEFAULT 0 CHECK(ordinal>=0), PRIMARY KEY(snapshot_id,artifact_id));
CREATE TABLE observations (observation_id varchar(64) PRIMARY KEY, tenant_id varchar(64) NOT NULL REFERENCES tenants(tenant_id) ON DELETE RESTRICT, project_id varchar(64) NOT NULL REFERENCES projects(project_id) ON DELETE RESTRICT, source_id varchar(64) REFERENCES sources(source_id) ON DELETE RESTRICT, created_at timestamptz NOT NULL DEFAULT now(), created_by varchar(128) NOT NULL, updated_at timestamptz NOT NULL DEFAULT now(), updated_by varchar(128) NOT NULL, version integer NOT NULL DEFAULT 1 CHECK(version>=1), row_version integer NOT NULL DEFAULT 1 CHECK(row_version>=1), status varchar(48) NOT NULL, classification varchar(48) NOT NULL DEFAULT 'INTERNAL', trace_id varchar(96), correlation_id varchar(96), schema_version integer NOT NULL DEFAULT 1 CHECK(schema_version>=1), valid_from timestamptz, valid_to timestamptz, system_from timestamptz NOT NULL DEFAULT now(), system_to timestamptz, deleted_at timestamptz, deletion_reason text, snapshot_id varchar(64) NOT NULL REFERENCES snapshots(snapshot_id) ON DELETE RESTRICT, artifact_id varchar(64) NOT NULL REFERENCES artifacts(artifact_id) ON DELETE RESTRICT, observed_at timestamptz NOT NULL, field varchar(255) NOT NULL, value jsonb NOT NULL, locator jsonb NOT NULL);
CREATE TABLE claims (claim_id varchar(64) PRIMARY KEY, tenant_id varchar(64) NOT NULL REFERENCES tenants(tenant_id) ON DELETE RESTRICT, project_id varchar(64) NOT NULL REFERENCES projects(project_id) ON DELETE RESTRICT, source_id varchar(64) REFERENCES sources(source_id) ON DELETE RESTRICT, created_at timestamptz NOT NULL DEFAULT now(), created_by varchar(128) NOT NULL, updated_at timestamptz NOT NULL DEFAULT now(), updated_by varchar(128) NOT NULL, version integer NOT NULL DEFAULT 1 CHECK(version>=1), row_version integer NOT NULL DEFAULT 1 CHECK(row_version>=1), status varchar(48) NOT NULL, classification varchar(48) NOT NULL DEFAULT 'INTERNAL', trace_id varchar(96), correlation_id varchar(96), schema_version integer NOT NULL DEFAULT 1 CHECK(schema_version>=1), valid_from timestamptz, valid_to timestamptz, system_from timestamptz NOT NULL DEFAULT now(), system_to timestamptz, deleted_at timestamptz, deletion_reason text, observation_id varchar(64) REFERENCES observations(observation_id) ON DELETE RESTRICT, subject varchar(500) NOT NULL, predicate varchar(255) NOT NULL, object_value jsonb NOT NULL, confidence_milli integer NOT NULL CHECK(confidence_milli BETWEEN 0 AND 1000), review_status varchar(32) NOT NULL DEFAULT 'EXTRACTED' CHECK(review_status IN ('EXTRACTED','PENDING_REVIEW','SUPPORTED','CONFIRMED','DISPUTED','REJECTED','SUPERSEDED','EXPIRED','QUARANTINED')), extractor_version varchar(128) NOT NULL, reviewed_at timestamptz);
CREATE TABLE evidence_links (evidence_link_id varchar(64) PRIMARY KEY, tenant_id varchar(64) NOT NULL REFERENCES tenants(tenant_id) ON DELETE RESTRICT, project_id varchar(64) NOT NULL REFERENCES projects(project_id) ON DELETE RESTRICT, source_id varchar(64) REFERENCES sources(source_id) ON DELETE RESTRICT, created_at timestamptz NOT NULL DEFAULT now(), created_by varchar(128) NOT NULL, updated_at timestamptz NOT NULL DEFAULT now(), updated_by varchar(128) NOT NULL, version integer NOT NULL DEFAULT 1 CHECK(version>=1), row_version integer NOT NULL DEFAULT 1 CHECK(row_version>=1), status varchar(48) NOT NULL, classification varchar(48) NOT NULL DEFAULT 'INTERNAL', trace_id varchar(96), correlation_id varchar(96), schema_version integer NOT NULL DEFAULT 1 CHECK(schema_version>=1), valid_from timestamptz, valid_to timestamptz, system_from timestamptz NOT NULL DEFAULT now(), system_to timestamptz, deleted_at timestamptz, deletion_reason text, claim_id varchar(64) NOT NULL REFERENCES claims(claim_id) ON DELETE RESTRICT, snapshot_id varchar(64) NOT NULL REFERENCES snapshots(snapshot_id) ON DELETE RESTRICT, artifact_id varchar(64) NOT NULL REFERENCES artifacts(artifact_id) ON DELETE RESTRICT, locator jsonb NOT NULL, CONSTRAINT uq_claim_evidence UNIQUE(claim_id,artifact_id,snapshot_id));
CREATE TABLE lot_source_links (lot_id varchar(64) NOT NULL REFERENCES lots(lot_id) ON DELETE RESTRICT, source_id varchar(64) NOT NULL REFERENCES sources(source_id) ON DELETE RESTRICT, created_at timestamptz NOT NULL DEFAULT now(), created_by varchar(128) NOT NULL, PRIMARY KEY(lot_id,source_id));
CREATE TABLE audit_events (audit_id bigserial PRIMARY KEY, tenant_id varchar(64) NOT NULL REFERENCES tenants(tenant_id) ON DELETE RESTRICT, project_id varchar(64) NOT NULL REFERENCES projects(project_id) ON DELETE RESTRICT, occurred_at timestamptz NOT NULL, event_type varchar(128) NOT NULL, actor_type varchar(32) NOT NULL, actor_id varchar(128) NOT NULL, entity_type varchar(128) NOT NULL, entity_id varchar(128) NOT NULL, trace_id varchar(96), correlation_id varchar(96), before_sha256 varchar(64), after_sha256 varchar(64), payload jsonb NOT NULL DEFAULT '{}'::jsonb, prev_event_sha256 varchar(64), event_sha256 varchar(64) NOT NULL UNIQUE);
CREATE TABLE server_state_revisions (revision bigserial PRIMARY KEY, tenant_id varchar(64) NOT NULL REFERENCES tenants(tenant_id) ON DELETE RESTRICT, project_id varchar(64) NOT NULL REFERENCES projects(project_id) ON DELETE RESTRICT, created_at timestamptz NOT NULL DEFAULT now(), sha256 varchar(64) NOT NULL, state jsonb NOT NULL, note text, restored_from bigint REFERENCES server_state_revisions(revision) ON DELETE RESTRICT, base_revision bigint NOT NULL DEFAULT 0, CONSTRAINT uq_state_revision_scope UNIQUE(tenant_id,project_id,revision));
CREATE TABLE schema_migrations (migration_id varchar(64) PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now(), sha256 varchar(64) NOT NULL, direction varchar(8) NOT NULL CHECK(direction IN ('UP','DOWN')));
ALTER TABLE lots ADD CONSTRAINT fk_lots_project_scope FOREIGN KEY (tenant_id,project_id) REFERENCES projects(tenant_id,project_id) ON DELETE RESTRICT;
ALTER TABLE sources ADD CONSTRAINT fk_sources_project_scope FOREIGN KEY (tenant_id,project_id) REFERENCES projects(tenant_id,project_id) ON DELETE RESTRICT;
ALTER TABLE source_versions ADD CONSTRAINT fk_source_versions_project_scope FOREIGN KEY (tenant_id,project_id) REFERENCES projects(tenant_id,project_id) ON DELETE RESTRICT;
ALTER TABLE source_policies ADD CONSTRAINT fk_source_policies_project_scope FOREIGN KEY (tenant_id,project_id) REFERENCES projects(tenant_id,project_id) ON DELETE RESTRICT;
ALTER TABLE connector_definitions ADD CONSTRAINT fk_connector_definitions_project_scope FOREIGN KEY (tenant_id,project_id) REFERENCES projects(tenant_id,project_id) ON DELETE RESTRICT;
ALTER TABLE collection_runs ADD CONSTRAINT fk_collection_runs_project_scope FOREIGN KEY (tenant_id,project_id) REFERENCES projects(tenant_id,project_id) ON DELETE RESTRICT;
ALTER TABLE artifacts ADD CONSTRAINT fk_artifacts_project_scope FOREIGN KEY (tenant_id,project_id) REFERENCES projects(tenant_id,project_id) ON DELETE RESTRICT;
ALTER TABLE snapshots ADD CONSTRAINT fk_snapshots_project_scope FOREIGN KEY (tenant_id,project_id) REFERENCES projects(tenant_id,project_id) ON DELETE RESTRICT;
ALTER TABLE observations ADD CONSTRAINT fk_observations_project_scope FOREIGN KEY (tenant_id,project_id) REFERENCES projects(tenant_id,project_id) ON DELETE RESTRICT;
ALTER TABLE claims ADD CONSTRAINT fk_claims_project_scope FOREIGN KEY (tenant_id,project_id) REFERENCES projects(tenant_id,project_id) ON DELETE RESTRICT;
ALTER TABLE evidence_links ADD CONSTRAINT fk_evidence_links_project_scope FOREIGN KEY (tenant_id,project_id) REFERENCES projects(tenant_id,project_id) ON DELETE RESTRICT;
CREATE INDEX ix_sources_tenant_project_status ON sources(tenant_id,project_id,status);
CREATE INDEX ix_artifacts_source_created_at ON artifacts(source_id,created_at);
CREATE INDEX ix_snapshots_source_captured_at ON snapshots(source_id,captured_at);
CREATE INDEX ix_claims_review_status_project_id ON claims(review_status,project_id);
CREATE INDEX ix_audit_events_project_occurred ON audit_events(project_id,occurred_at);
COMMIT;
